<script lang="ts">import type { Snippet } from 'svelte'; import type { HTMLButtonAttributes } from 'svelte/elements'; import { composeEventHandlers } from '../shared/events.js'; import { getToastItemContext, getToastProviderContext } from './toast-context.svelte.js'; interface Props extends Omit<HTMLButtonAttributes, 'children'> { children?: Snippet; ref?: HTMLButtonElement | null; } let { children, ref = $bindable(null), onclick, ...rest }: Props = $props(); const provider = getToastProviderContext(); const item = getToastItemContext();</script><button bind:this={ref} {...rest} type="button" aria-label={rest['aria-label'] ?? (children ? undefined : 'Close notification')} onclick={composeEventHandlers(onclick, () => provider.close(item.toast.id))}>{@render children?.()}</button>
